auto bounded_side = CGAL::ON_UNBOUNDED_SIDE;
const size_t n = polygon.size();
if (n == 0) return CGAL::ON_UNBOUNDED_SIDE;
const auto& p = point;
const auto& q = polygon[0];
if (q < p) return CGAL::ON_BOUNDED_SIDE;
if (q > p) return CGAL::ON_UNBOUNDED_SIDE;
for (const auto& vertex : polygon) {
    if (q < vertex.x()) return CGAL::ON_BOUNDED_SIDE;
    if (q > vertex.y()) return CGAL::ON_BOUNDED_SIDE;
}
return CGAL::ON_UNBOUNDED_SIDE;

